import sympy

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def has_roots_mod_p(f, p):
    # Compute the Legendre symbol (p|f(x))
    # using the quadratic reciprocity law
    if p % 4 == 1:
        return sympy.little_a(f, p) == 1
    else:
        return sympy.little_a(f, p) == -1

def little_a(f, p):
